#include "navigation.h"
#include <bits/stdc++.h>
using namespace std;
static const char*TA="",*TB="";
static int S,W[4];
static const char*T;
static void I(int B){if(B<4){S=5;T=TA;W[0]=7;W[1]=25;W[2]=30;W[3]=2;}else{S=4;T=TB;W[0]=W[1]=W[2]=15;W[3]=1;}}
static int O(vector<int>&c,vector<int>&v){int m[5]={0,0,0,0,0},k=0,q=1;for(int x:c)m[x]++;for(int i=0;i<S;i++)k+=min(m[i],3)*q,q*=4;for(size_t i=0;i<c.size();i++)if(T[k*S+c[i]]!='0'+v[i])return 0;return 1;}
static vector<int>g;static vector<int>vv;static int zz;
static int F(size_t i,int lo){if(i==vv.size())return O(g,vv);int v=vv[i];int b=(i>=vv.size()-zz)?W[0]:W[v];for(int c=0;c<S;c++)if(b>>c&1){if(i>=vv.size()-zz&&c<lo)continue;if(zz==3&&i>vv.size()-3&&c!=g[i-1])continue;g[i]=c;if(F(i+1,i>=vv.size()-zz?c:0))return 1;}return 0;}
static map<vector<int>,vector<int>>M;
static vector<int> Z(int p,int s,vector<int>pt,int z){vector<int>k=pt;k.push_back(p);k.push_back(s);k.push_back(z);auto it=M.find(k);if(it!=M.end())return it->second;vv.clear();g.clear();if(p>=0){vv.push_back(6-s);g.push_back(p);}for(int x:pt)vv.push_back(x),g.push_back(0);for(int i=0;i<z;i++)vv.push_back(0),g.push_back(0);zz=z;size_t o=p>=0;vector<int>r;if(F(o,0))r=vector<int>(g.begin()+o,g.end());M[k]=r;return r;}
vector<int> construct_network(int N,int K,int B,vector<int>U,vector<int>V,vector<int>P){I(B);M.clear();vector<vector<pair<int,int>>>a(N);for(int i=0;i<N-1;i++)a[U[i]].push_back({V[i],i}),a[V[i]].push_back({U[i],i});vector<int>t(N,0),f(N,-1),o,c(N,0),s(N,0),pc(N,-1),T2(N-1,0);for(int x:P)t[x]=1;auto bf=[&](int r){o.clear();f.assign(N,-1);f[r]=r;o.push_back(r);for(size_t i=0;i<o.size();i++){int u=o[i];for(auto[w,e]:a[u])if(f[w]<0)f[w]=u,pc[w]=e,o.push_back(w);}for(int i=N-1;i>=0;i--){int u=o[i];c[u]=t[u];for(auto[w,e]:a[u])if(w!=f[u])c[u]+=c[w];}};bf(0);int r=-1;for(int u=0;u<N;u++){int m=K-c[u];for(auto[w,e]:a[u])if(w!=f[u])m=max(m,c[w]);if(m<=3&&(r<0||(t[u]&&!t[r])))r=u;}bf(r);for(int u:o){vector<pair<int,int>>ch;for(auto[w,e]:a[u])if(w!=f[u])ch.push_back({c[w],e});if(ch.empty())continue;if(t[u]){for(auto[v,e]:ch){int b=W[v],q=0;while(!(b>>q&1))q++;T2[e]=q;}continue;}sort(ch.rbegin(),ch.rend());vector<int>pt;int z=0;for(auto[v,e]:ch)if(v)pt.push_back(v);else z++;int p=-1,sv=0;if(u!=r){p=T2[pc[u]];sv=c[u];}vector<int>q=Z(p,sv,pt,min(z,3));for(size_t i=0;i<ch.size();i++)T2[ch[i].second]=q[min(i,q.size()-1)];}return T2;}
vector<int> navigate(int K,int B,vector<int>C){I(B);int m[5]={0,0,0,0,0},k=0,q=1;for(int x:C)m[x]++;for(int i=0;i<S;i++)k+=min(m[i],3)*q,q*=4;vector<int>d;for(int x:C)d.push_back(T[k*S+x]-'0');return d;}
